use pyo3_stub_gen::generate::ClassDef;

/// Generates `_mysoc_validator_fast.pyi` from the bridge modules' pyo3-stub-gen annotations.
///
/// Run from the workspace root:
///   cargo run --manifest-path mysoc_validator_fast/Cargo.toml --bin stub_gen
///
/// Pass an optional output directory after `--` to preview generated stubs
/// outside the Python package. The checked-in file also has hand-maintained
/// transcript and compatibility declarations: inspect the generated diff before
/// replacing it.
fn main() -> pyo3_stub_gen::Result<()> {
    // stub_info() is generated by define_stub_info_gatherer! in lib.rs
    let mut stub = _mysoc_validator_fast::stub_info()?;
    if let Some(output) = std::env::args_os().nth(1) {
        stub.python_root = output.into();
    }
    for module in stub.modules.values_mut() {
        for class in module.class.values_mut() {
            normalize_class_identifiers(class);
        }
    }
    stub.generate()?;
    Ok(())
}

/// Strip Rust raw-identifier prefixes that pyo3-stub-gen 0.23 emits verbatim.
fn normalize_class_identifiers(class: &mut ClassDef) {
    for member in class.attrs.iter_mut().chain(
        class
            .getter_setters
            .values_mut()
            .flat_map(|(getter, setter)| getter.iter_mut().chain(setter.iter_mut())),
    ) {
        member.name = member.name.strip_prefix("r#").unwrap_or(member.name);
    }
    for method in class.methods.values_mut().flatten() {
        method.name = method.name.strip_prefix("r#").unwrap_or(method.name);
        let parameters = &mut method.parameters;
        for parameter in parameters
            .positional_only
            .iter_mut()
            .chain(parameters.positional_or_keyword.iter_mut())
            .chain(parameters.keyword_only.iter_mut())
            .chain(parameters.varargs.iter_mut())
            .chain(parameters.varkw.iter_mut())
        {
            parameter.name = parameter.name.strip_prefix("r#").unwrap_or(parameter.name);
        }
    }
    for nested in &mut class.classes {
        normalize_class_identifiers(nested);
    }
}
